import React from "react";

// PeruDocumentoNacionalDeIdentidadView component
//
// A headless display component for showing Peru's
// Documento Nacional de Identidad (DNI) in a read-only format.
//
// Props:
//   className — string, optional. CSS class name.
//   label — string, optional. Hidden text naming the value. Leave it out when a visible caption, such as a dt or a SummaryListItem term, already names it.
//   value — string, default "". The identifier string to display.
//   ...restProps — additional HTML attributes spread onto the <span>.
//
// Syntax:
//   <PeruDocumentoNacionalDeIdentidadView label="Documento Nacional de Identidad (DNI)" value={value} />
//
// Accessibility:
//   - A visible caption names the value, or label renders as hidden text; a plain span cannot take aria-label.
//
// References:
//   - https://es.wikipedia.org/wiki/Documento_Nacional_de_Identidad_(Per%C3%BA)

export interface PeruDocumentoNacionalDeIdentidadViewProps {
    className?: string;
    /** Accessible label for screen readers */
    label?: string;
    /** The identifier to display */
    value?: string;
    [key: string]: unknown;
}

export default function PeruDocumentoNacionalDeIdentidadView({
    className = "",
    label,
    value = "",
    ...restProps
}: PeruDocumentoNacionalDeIdentidadViewProps) {
    return (
        <span
            className={`peru-documento-nacional-de-identidad-view ${className}`}
            {...restProps}
        >
            {label ? <span className="screen-reader-span">{`${label} `}</span> : null}
            {value}
        </span>
    );
}
